          var vs = (d0 + d1)/2;
          var dw = Math.abs(x1 - x0);
          if (dw < 0.05){ px = nx; pz = nz; continue; }

          /* the sheet's normal points at the eye while cos(a) is positive */
          var front = Math.cos(a) > 0;
