      /* the gutter */
      var g = ctx.createLinearGradient(spineX - BW*0.05, 0, spineX + BW*0.05, 0);
      g.addColorStop(0,   'rgba(0,0,0,0)');
      g.addColorStop(0.5, 'rgba(0,0,0,0.62)');
      g.addColorStop(1,   'rgba(0,0,0,0)');
